   140  static int
   141  asn1_decode_pbkdf2_params(sc_context_t *ctx, void **paramp,
   142                                  const u8 *buf, size_t buflen, int depth)
   143  {
   144          struct sc_pbkdf2_params info;
   145          struct sc_asn1_entry asn1_pbkdf2_params[5];
   146          int r;
   147
   148          sc_copy_asn1_entry(c_asn1_pbkdf2_params, asn1_pbkdf2_params);
   149          sc_format_asn1_entry(asn1_pbkdf2_params + 0,
   150                          info.salt, &info.salt_len, 0);
   151          sc_format_asn1_entry(asn1_pbkdf2_params + 1,
   152                          &info.iterations, NULL, 0);
   153          sc_format_asn1_entry(asn1_pbkdf2_params + 2,
   154                          &info.key_length, NULL, 0);
   155          sc_format_asn1_entry(asn1_pbkdf2_params + 3,
   156                          &info.hash_alg, NULL, 0);
   157
   158          memset(&info, 0, sizeof(info));
   159          info.salt_len = sizeof(info.salt);
   160          info.hash_alg.algorithm = SC_ALGORITHM_SHA1;
   161
   162          r = _sc_asn1_decode(ctx, asn1_pbkdf2_params, buf, buflen, NULL, NULL, 0, depth + 1);
   163          if (r < 0)
   164                  return r;
   165
   166          *paramp = malloc(sizeof(info));
   167          if (!*paramp)
   168                  return SC_ERROR_OUT_OF_MEMORY;
   169          memcpy(*paramp, &info, sizeof(info));
   170          return 0;
   171  }
