   462  static struct sc_asn1_pkcs15_algorithm_info *
   463  sc_asn1_get_algorithm_info(const struct sc_algorithm_id *id)
   464  {
   465          struct sc_asn1_pkcs15_algorithm_info *aip = NULL;
   466
   467          for (aip = algorithm_table; aip->id >= 0; aip++)   {
   468                  if ((int) id->algorithm < 0 && sc_compare_oid(&id->oid, &aip->oid))
   469                          return aip;
   470
   471                  if (aip->id == (int)id->algorithm)
   472                          return aip;
   473          }
   474
   475          return NULL;
   476  }
